cd /tmp/ross-main && python3 - <<'PY'
import sys, re, glob, collections
sys.path.insert(0,"/tmp")
from lib_parse import all_msgs
msgs=all_msgs()
problems=[]
for f in sorted(glob.glob("S*/E*.md")):
    t=open(f).read()
    ep=re.search(r"^episode: (\d+)", t, re.M).group(1)
    season=re.search(r"^season: (\d+)", t, re.M).group(1)
    want=f"S{int(season):02d}/E{int(ep):02d}"
    if f"{season}/{ep}" not in f: pass
    for m in re.finditer(r"\*\*(\w+)\*\* \(([^)]+)\)\n\nSource: friend/([a-z]+) @ ([0-9a-f]{40})", t):
        speaker, ts, branch, sha = m.groups()
        v=msgs.get(sha)
        if not v: problems.append((f,sha,"unknown sha")); continue
        if v["speaker"]!=speaker: problems.append((f,sha,f"speaker {speaker} vs {v['speaker']}"))
        if v["branch"]!=branch: problems.append((f,sha,f"branch {branch} vs {v['branch']}"))
        if v["ci"]!=ts: problems.append((f,sha,f"time {ts} vs {v['ci']}"))
        if v["ep"]!=want: problems.append((f,sha,f"declared {v['ep']} filed in {want}"))
print("integrity problems:",len(problems))
for p in problems[:15]: print("  ",p)
PY

